#Region @DOC
#### Description:
#Copies dimension hierarchies from a source database to a target database. Each hierarchy is exported to a CSV file with `}bedrock.hier.export` on the source, moved with `}bedrock.migrate.file`, and imported with `}bedrock.hier.import` on the target.
#
#### How to Use:
#
#- `pDimension`: REQUIRED: the dimension name(s) (see patterns below).
#- `pHierarchy`: OPTIONAL: the hierarchy name(s) or pattern(s) within each dimension. If blank, only the hierarchy with the same name as each matched dimension is copied (matched exactly, not as a pattern); `*` copies all hierarchies.
#- `pIncludeControlObjects`: 1 = also copy matching control dimensions (names starting with `}`).
#- `pSkipLeavesHierarchy`: 1 = skip the `Leaves` hierarchy (default). With 0, `Leaves` is copied only where the target dimension already has a `Leaves` hierarchy; otherwise an error is added.
#- `pUnwind`: what happens to the target hierarchy before the import. 0 = delete all its elements first, so the target ends up as a copy of the source (default). **Warning:** with 0, elements that exist only on the target are deleted, and with them their data in every cube that uses the dimension. 1 = unwind the existing consolidations (`pConsol`) and keep all elements. 2 = do not change existing elements, only add; use 2 to keep target-only elements and their data.
#- `pConsol`: the target consolidations to unwind when `pUnwind` = 1.
#- `pOutputQuoteCharacter`: the quote character of the CSV file, used by both the export and the import.
#- `pSourceConnectionName` / `pTargetConnectionName`: connection names configured in `}bedrock.session.start`, or connection-details JSON objects returned by it. A blank name means this database. When a JSON object is passed, that session is reused and is not closed at the end of this process.
#- `pLogOutput`, `pStrictErrorHandling` and `pJson` work as in all bedrock processes. Connection-details objects are logged as their URL only.
#
#The object name parameter accepts:
#- a single name, e.g. `Sales`
#- a wildcard pattern, e.g. `Sales*`
#- several names or patterns separated by `&`, e.g. `Sales* & Cost*`
#- a JSON Array of names or patterns, e.g. `["Sales*", "Cost*"]`
#
#The dimensions and hierarchies are matched against the source database.
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUsername|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pConsol":               "*",
  "pDimension":            null,
  "pHierarchy":            "",
  "pIncludeControlObjects": 0,
  "pOutputQuoteCharacter": "\"",
  "pSourceConnectionName": null,
  "pTargetConnectionName": null,
  "pLogOutput":            0,
  "pSkipLeavesHierarchy":  1,
  "pStrictErrorHandling":  0,
  "pUnwind":               0
}';

pPassedParameters = '{
  "pConsol":               '|StringToJson  ( pConsol               )|',
  "pDimension":            '|StringToJson  ( pDimension            )|',
  "pHierarchy":            '|StringToJson  ( pHierarchy            )|',
  "pIncludeControlObjects": '|NumberToString( pIncludeControlObjects )|',
  "pOutputQuoteCharacter": '|StringToJson  ( pOutputQuoteCharacter )|',
  "pSourceConnectionName": '|StringToJson  ( pSourceConnectionName )|',
  "pTargetConnectionName": '|StringToJson  ( pTargetConnectionName )|',
  "pLogOutput":            '|NumberToString( pLogOutput            )|',
  "pSkipLeavesHierarchy":  '|NumberToString( pSkipLeavesHierarchy  )|',
  "pStrictErrorHandling":  '|NumberToString( pStrictErrorHandling  )|',
  "pUnwind":               '|NumberToString( pUnwind               )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pConsol               =                 JsonToString( pJson, '/pConsol'               );
pDimension            =                 JsonToString( pJson, '/pDimension'            );
pHierarchy            =                 JsonToString( pJson, '/pHierarchy'            );
pOutputQuoteCharacter =                 JsonToString( pJson, '/pOutputQuoteCharacter' );
IF( JsonType( JsonGet( pJson, '/pSourceConnectionName' ) ) @= 'string' );
  pSourceConnectionName = JsonToString( pJson, '/pSourceConnectionName' );
ELSE;
  pSourceConnectionName = JsonGet( pJson, '/pSourceConnectionName' );
ENDIF;
IF( JsonType( JsonGet( pJson, '/pTargetConnectionName' ) ) @= 'string' );
  pTargetConnectionName = JsonToString( pJson, '/pTargetConnectionName' );
ELSE;
  pTargetConnectionName = JsonGet( pJson, '/pTargetConnectionName' );
ENDIF;
# Numeric Parameters
pIncludeControlObjects = StringToNumber( JsonToString( pJson, '/pIncludeControlObjects' ) );
pLogOutput            = StringToNumber( JsonToString( pJson, '/pLogOutput'            ) );
pSkipLeavesHierarchy  = StringToNumber( JsonToString( pJson, '/pSkipLeavesHierarchy'  ) );
pStrictErrorHandling  = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling'  ) );
pUnwind               = StringToNumber( JsonToString( pJson, '/pUnwind'               ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

### Connection-details objects are logged as their URL only
IF( JsonType( pSourceConnectionName ) @= 'object' );
  pPassedParameters = JsonReplace( pPassedParameters, '/pSourceConnectionName', StringToJson( JsonToString( pSourceConnectionName, '/sURL' ) ) );
ENDIF;
IF( JsonType( pTargetConnectionName ) @= 'object' );
  pPassedParameters = JsonReplace( pPassedParameters, '/pTargetConnectionName', StringToJson( JsonToString( pTargetConnectionName, '/sURL' ) ) );
ENDIF;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

IF( pDimension @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"pDimension is required."' );
  ProcessBreak;
ENDIF;

# Get Database Connection Details
sSourceDatabaseParameterType = JsonType( pSourceConnectionName );
IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pSourceConnectionName, 'pJson', pJson ); sSourceConnectionDetails = sBedrockReturnValue;
ELSE;
  sSourceConnectionDetails = pSourceConnectionName;
ENDIF;
pJson = JsonAdd( pJson, 'pSourceConnectionName', sSourceConnectionDetails );

sTargetDatabaseParameterType = JsonType( pTargetConnectionName );
IF( sTargetDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pTargetConnectionName, 'pJson', pJson ); sTargetConnectionDetails = sBedrockReturnValue;
ELSE;
  sTargetConnectionDetails = pTargetConnectionName;
ENDIF;
pJson = JsonAdd( pJson, 'pTargetConnectionName', sTargetConnectionDetails );

sSourceURL = JsonToString( sSourceConnectionDetails, '/sURL' );
sTargetURL = JsonToString( sTargetConnectionDetails, '/sURL' );
IF( sSourceURL @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"Could not start a session on the source database."' );
ENDIF;
IF( sTargetURL @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"Could not start a session on the target database."' );
ENDIF;

### Authentication headers for requests to this connection
sSrcAuthHeaders = '[]';
IF( JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sSourceConnectionDetails, '/sSID' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sSourceConnectionDetails, '/sSID' ) ) );
ENDIF;

### Authentication headers for requests to this connection
sTgtAuthHeaders = '[]';
IF( JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sTargetConnectionDetails, '/sSID' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sTargetConnectionDetails, '/sSID' ) ) );
ENDIF;

IF( JsonSize( pDimension ) = -1 );
  ExecuteProcess( '}bedrock.utils.string.to_list', 'pString', pDimension, 'pDelimiter', '&', 'pTRIM', 1 );
  pDimension = sBedrockReturnValue;
ENDIF;

IF( pHierarchy @<> '' & JsonSize( pHierarchy ) = -1 );
  ExecuteProcess( '}bedrock.utils.string.to_list', 'pString', pHierarchy, 'pDelimiter', '&', 'pTRIM', 1 );
  pHierarchy = sBedrockReturnValue;
ENDIF;

### If errors occurred, stop; the Epilog cleans up and quits in strict mode ###
IF( JsonSize( sMessages, '/Error' ) <> 0 );
  ProcessBreak;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Setup Execute Http Request Parameters

# Process Constants
cHierExport = '}bedrock.hier.export';
cHierImport = '}bedrock.hier.import';

# Get Database Source Details
sSourceVer = JsonToString( sSourceConnectionDetails, '/sVer' );
sSourceDBN = JsonToString( sSourceConnectionDetails, '/sDBN' );

# Get Database Target Details
sTargetVer = JsonToString( sTargetConnectionDetails, '/sVer' );
sTargetDBN = JsonToString( sTargetConnectionDetails, '/sDBN' );

# Get the process error directory, because Bedrock 4 defaults to it.
IF( StringToNumber( SUBST( sSourceVer, 1, 2 ) ) < 12 );
  sSrcDir = 'ERROR - Did not get directory for database with version <12.';
ELSE;
  sSrcDir = '.';
ENDIF;

IF( StringToNumber( SUBST( sTargetVer, 1, 2 ) ) < 12 );
  sTgtDir = 'ERROR - Did not get directory for database with version <12.';
ELSE;
  sTgtDir = '.';
ENDIF;

# Create Parameters for }bedrock.hier.export and }bedrock.hier.import
sParameters = '{
  "pTgtDir": '|StringToJson( sSrcDir )|', 
  "pSrcDir": '|StringToJson( sTgtDir )|', 
  "pDelim": ",",
  "pTitleRecord": 1,
  "pQuote": '|StringToJson( pOutputQuoteCharacter )|'
}';
pJson = JsonAdd( pJson, 'pProcessParameters', sParameters );

#EndRegion - Setup Execute Http Request Parameters
#################################################################################################

#################################################################################################
#Region - Create Datasource

# Get Dimensions that match pDimension
sDimensionMDX = '';
nCount = JsonSize( pDimension );
WHILE( nCount > 0 );
  nCount = nCount - 1;
  sDimension = JsonToString( JsonGet( pDimension, nCount ) );

  sDimensionMDX = sDimensionMDX | ', {TM1FILTERBYPATTERN(TM1SUBSETALL([}Dimensions].[}Dimensions]), "'|sDimension|'")}';
END;

# Remove Hierarchies
sDimensionMDX = '{EXCEPT({'|DELET( sDimensionMDX, 1, 2 )|'}, {TM1FILTERBYPATTERN({TM1SUBSETALL([}Dimensions].[}Dimensions])},"*:*")})}';
# Remove Control Objects
IF( pIncludeControlObjects = 0 );
  sDimensionMDX = '{EXCEPT('|sDimensionMDX|', {TM1FILTERBYPATTERN({TM1SUBSETALL([}Dimensions].[}Dimensions])},"}*")})}';
ENDIF;

# Get Dimensions/Hierarchies that match pHierarchy; blank keeps only the same-named hierarchy
IF( JsonSize( pHierarchy ) > 0 );
  sHierarchyMDX = '';
  nCount = JsonSize( pHierarchy );
  WHILE( nCount > 0 );
    nCount = nCount - 1;
    sHierarchy = JsonToString( JsonGet( pHierarchy, nCount ) );

    sDimGenerateMDX  = '{TM1FILTERBYPATTERN({[}Dimensions].[}Dimensions].CurrentMember}, "'|sHierarchy|'")}';
    sHierGenerateMDX = '{TM1FILTERBYPATTERN({TM1SUBSETALL([}Dimensions].[}Dimensions])}, [}Dimensions].[}Dimensions].CurrentMember.Name+":'|sHierarchy|'")}';
    sHierMDX = 'GENERATE('|sDimensionMDX|', {'|sDimGenerateMDX|','|sHierGenerateMDX|'})';
    sHierarchyMDX = sHierarchyMDX | ', ' | sHierMDX;

  END;
  sHierarchyMDX = '{DISTINCT({' | DELET( sHierarchyMDX, 1, 1 ) | '})}';
ELSE;
  sHierarchyMDX = sDimensionMDX;
ENDIF;

# Get the matching dimensions/hierarchies from the source database
nRet = ExecuteProcess('}bedrock.process.execute_http_request',
  'pMethod', 'POST',
  'pURL', sSourceURL | '/ExecuteMDXSetExpression?$expand=Tuples($expand=Members($select=Name))',
  'pBody', '{"MDX":'|StringToJson( sHierarchyMDX )|'}',
  'pHeaders', JsonAdd( sSrcAuthHeaders, '', '"Content-Type:application/json; charset=utf-8"' ),
  'pResponseFile', cTemp|'.blb',
  'pJson', pJson );
nStatusCode = StringToNumber( JsonToString( sBedrockReturnValue, '/status_code' ) );
IF( nRet <> ProcessExitNormal() % nStatusCode < 200 % nStatusCode >= 300 );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Listing the matching objects on the source database failed (HTTP status ' | NumberToString( nStatusCode ) | ').' ) );
  ProcessBreak;
ENDIF;

# Datasource Parameters
DatasourceType = 'JSON';
DatasourceJsonRootPointer = '/Tuples';
DatasourceJsonVariableMapping = '{
  "vDimension": "/Members/0/Name"
}';
DatasourceNameForServer = cTemp|'.blb';

# Counted in the Data tab
nMatches = 0;

#EndRegion - Create Datasource
#################################################################################################

DataProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

vDimension = JsonToString( vDimension );
nMatches = nMatches + 1;

# Get sDimension and sHierarchy from vDimension
nColonIndex = SCAN( ':', vDimension );
IF( nColonIndex <> 0 );
  sDimension = SUBST( vDimension, 1, nColonIndex-1 );
  sHierarchy = DELET( vDimension, 1, nColonIndex );
ELSE;
  sDimension = vDimension;
  sHierarchy = vDimension;
ENDIF;

IF( pSkipLeavesHierarchy = 1 & sHierarchy @= 'Leaves' );
  ITEMSKIP;
ENDIF;

# Leaves is maintained by the server, so it can only be copied where the target already has it
IF( sHierarchy @= 'Leaves' );
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod', 'GET',
    'pURL', sTargetURL | '/Dimensions(''' | URLEncode( sDimension ) | ''')/Hierarchies(''Leaves'')?$select=Name',
    'pHeaders', sTgtAuthHeaders,
    'pLogOutput', pLogOutput );
  IF( StringToNumber( JsonToString( sBedrockReturnValue, '/status_code' ) ) = 404 );
    sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Dimension ''' | sDimension | ''' has no Leaves hierarchy on the target database, so Leaves cannot be copied. The server creates it once the dimension has more than one hierarchy; copy those first.' ) );
    ITEMSKIP;
  ENDIF;
ENDIF;

#################################################################################################
#Region - Execute Http Requests to Migrate Hierarchy

# Add sDimension, sHierarchy, and sFileName Parameters
sFileName = StringToJson( cTemp|'_'|sDimension|'_'|sHierarchy|'.csv' );
pJson = JsonAdd( pJson, '/pDim',     StringToJson( sDimension ) );
pJson = JsonAdd( pJson, '/pHier',    StringToJson( sHierarchy ) );
pJson = JsonAdd( pJson, '/pTgtFile', sFileName );
pJson = JsonAdd( pJson, '/pSrcFile', sFileName );
pJson = JsonAdd( pJson, '/pProcessParameters/pJson', StringToJson( JsonRemove( pJson, '/pProcessParameters' ) ) );

# Execute cHierExport on the source database
pJson = JsonAdd( pJson, 'pProcess', StringToJson( cHierExport ) );
pJson = JsonAdd( pJson, 'pTargetConnectionName', sSourceConnectionDetails );
nRet = ExecuteProcess( '}bedrock.process.execute_externally', 'pJson', pJson );
IF( nRet <> ProcessExitNormal() );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Exporting hierarchy ''' | sDimension | ':' | sHierarchy | ''' on the source database failed.' ) );
  ProcessBreak;
ENDIF;

# The export set the target to the source; migrate.file reads pTargetConnectionName from pJson too
pJson = JsonAdd( pJson, 'pTargetConnectionName', sTargetConnectionDetails );

# Transfer the file from source database to target database
nRet = ExecuteProcess( '}bedrock.migrate.file',
  'pFile',                 cTemp|'_'|sDimension|'_'|sHierarchy|'.csv',
  'pTargetPath',           '',
  'pDeleteSourceFile',     1,
  'pSourceConnectionName', sSourceConnectionDetails,
  'pTargetConnectionName', sTargetConnectionDetails,
  'pJson', pJson );
IF( nRet <> ProcessExitNormal() );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Copying the file of hierarchy ''' | sDimension | ':' | sHierarchy | ''' to the target database failed.' ) );
  ProcessBreak;
ENDIF;

# Execute cHierImport on the target database
pJson = JsonAdd( pJson, 'pProcess', StringToJson( cHierImport ) );
nRet = ExecuteProcess( '}bedrock.process.execute_externally', 'pJson', pJson );
IF( nRet <> ProcessExitNormal() );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Importing hierarchy ''' | sDimension | ':' | sHierarchy | ''' on the target database failed.' ) );
  ProcessBreak;
ENDIF;

# Delete the file from the target
ExecuteProcess( '}bedrock.process.execute_http_request',
  'pMethod', 'DELETE',
  'pURL', sTargetURL | '/Contents(''Files'')/Contents(''' | URLEncode( cTemp|'_'|sDimension|'_'|sHierarchy|'.csv' ) | ''')',
  'pHeaders', sTgtAuthHeaders,
  'pLogOutput', pLogOutput );

#EndRegion - Execute Http Requests to Migrate Hierarchy
#################################################################################################

EpilogProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

##################################################################################################
##Region - Cleanup
IF( FileExists( cTemp|'.blb' ) = 1 );
  ASCIIDelete( cTemp|'.blb' );
ENDIF;

IF( sSourceDatabaseParameterType @<> 'object' & sSourceURL @<> '' );
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sSourceURL | '/ActiveSession/tm1.Close',
    'pHeaders', JsonAdd( sSrcAuthHeaders, '', '"Content-Type:application/json; charset=utf-8"' ),
    'pJson', pJson 
  );
ENDIF;
IF( sTargetDatabaseParameterType @<> 'object' & sTargetURL @<> '' );
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sTargetURL | '/ActiveSession/tm1.Close',
    'pHeaders', JsonAdd( sTgtAuthHeaders, '', '"Content-Type:application/json; charset=utf-8"' ),
    'pJson', pJson 
  );
ENDIF;

#EndRegion - Cleanup
#################################################################################################

#################################################################################################
#Region - Check Errors

IF( nMatches = 0 & JsonSize( sMessages, '/Error' ) = 0 );
  sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'No hierarchy on the source database matches dimension ' | pDimension | ', hierarchy ' | pHierarchy | '.' ) );
ENDIF;

IF( JsonSize( sMessages, '/Error' ) <> 0 );
  LogOutput( 'ERROR', JsonToString( sMessages, '/Error/0' ) );
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ENDIF;
ENDIF;

#EndRegion - Check Errors
#################################################################################################
